import{_ as e,r as c,o,b as d,a,d as n,w as i,y as l,e as p}from"./index-0e2c1b00.js";const f={},v={class:"reaction-more-page"},r={class:"content-wrapper"},b={class:"header-section"};function _(x,t){const s=c("router-link");return o(),d("div",v,[a("div",r,[a("div",b,[n(s,{to:"/game",class:"back-button"},{default:i(()=>[...t[0]||(t[0]=[p(" ← 返回 ",-1)])]),_:1}),t[1]||(t[1]=a("h1",{class:"title"},"反应时",-1))]),t[2]||(t[2]=l('<div class="card" data-v-9d5b2f5a><section class="section" data-v-9d5b2f5a><h2 class="section-title" data-v-9d5b2f5a>一、权威定义（实验心理学标准表述）</h2><p class="section-text" data-v-9d5b2f5a> 反应时（Reaction Time, RT），指从特定刺激呈现到被试做出明确外显反应之间的精确时间间隔，是衡量人类感知觉加工、注意分配、决策速度、动作执行的核心行为指标，由唐德斯（F.C. Donders）于 19 世纪中叶建立实验室测量范式，为认知心理学奠基方法之一。 </p></section><section class="section" data-v-9d5b2f5a><h2 class="section-title" data-v-9d5b2f5a>二、本项目反应时挑战的权威定位</h2><p class="section-text" data-v-9d5b2f5a> 任务类型：辨别反应时（C 类反应时）—— 单一目标刺激（绿色）需反应，干扰刺激（其他颜色）不反应，测量刺激辨别 + 动作触发的时间成本。 </p><p class="section-text" data-v-9d5b2f5a> 测量逻辑：刺激出现时刻→视觉编码→特征辨别→决策→运动执行→按键响应，全程精确到毫秒。 </p><p class="section-text" data-v-9d5b2f5a> 数据属性：客观、连续、可建模，服从正态分布，可做群体参照与个体差异分析。 </p><p class="section-text" data-v-9d5b2f5a> 伦理边界：仅科普与量化体验，不做病理判断、不替代心理评估、不涉及敏感信息采集。 </p></section><section class="section" data-v-9d5b2f5a><h2 class="section-title" data-v-9d5b2f5a>三、标准流程（权威范式简化版）</h2><p class="section-text" data-v-9d5b2f5a> 指导语标准化：明确 “仅在绿色出现时立即按键，其他颜色不做反应”。 </p><p class="section-text" data-v-9d5b2f5a> 刺激呈现：随机色块序列，目标为绿色，其余为干扰色。 </p><p class="section-text" data-v-9d5b2f5a> 数据采集：逐试次记录试次序号、反应时、反应正确性。 </p><p class="section-text" data-v-9d5b2f5a> 可视化：正态分布直方 — 折线图，标注个体在大学生群体中的相对水平。 </p></section><section class="section" data-v-9d5b2f5a><h2 class="section-title" data-v-9d5b2f5a>四、核心指标与解释（权威口径）</h2><p class="section-text" data-v-9d5b2f5a> 反应时：越小代表信息加工越快、注意越集中、动作越敏捷。 </p><p class="section-text" data-v-9d5b2f5a> 正确率：反映任务遵守度与辨别稳定性，错误率过高提示注意波动。 </p><p class="section-text" data-v-9d5b2f5a> 分布特征：健康大学生群体反应时呈正态分布，极端快 / 慢占比低，中等速度占比最高。 </p></section><section class="section" data-v-9d5b2f5a><h2 class="section-title" data-v-9d5b2f5a>五、合规声明（必写权威表述）</h2><p class="section-text" data-v-9d5b2f5a> 本反应时挑战为心理建模科普游戏，基于实验心理学经典范式设计，仅用于展示心理活动可量化特征，不构成任何心理诊断、健康评估或临床结论；数据匿名采集，仅用于历史查询与科普研究，严格遵循《个人信息保护法》相关要求。 </p></section></div>',1))])])}const m=e(f,[["render",_],["__scopeId","data-v-9d5b2f5a"]]);export{m as default};
